 1	import { useQuery } from "@tanstack/react-query";
 2	import { Link, useParams } from "react-router";
 3	import { Card } from "../components/Card/Card";
 4	import { cx } from "../lib/class-names";
 5	import { getPostListQueryOptions } from "../queries/posts/post-list-query";
 6	import css from "./PostListPage.module.css";
 7	
 8	export function PostListPage() {
 9	  const { siteSlug = "" } = useParams();
10	  const postsQuery = useQuery(getPostListQueryOptions(siteSlug));
11	
12	  return (
13	    <section>
14	      <h1 className={css.heading}>Posts</h1>
15	
16	      {postsQuery.isPending && <p>Loading posts…</p>}
17	
18	      {postsQuery.isError && (
19	        <p role="alert">Couldn't load this site's posts. Try reloading the page.</p>
20	      )}
21	
22	      {postsQuery.isSuccess && postsQuery.data.length === 0 && (
23	        <p>This site doesn't have any posts yet.</p>
24	      )}
25	
26	      {postsQuery.isSuccess && postsQuery.data.length > 0 && (
27	        <ul className={css.list} aria-label="Posts">
28	          {postsQuery.data.map((post) => (
29	            <li key={post.id}>
30	              <Link to={`/sites/${siteSlug}/posts/${post.id}`} className={css.cardLink}>
31	                <Card>
32	                  <p className={css.title}>{post.title}</p>
33	                  <div className={css.meta}>
34	                    <span
35	                      className={cx(
36	                        css.status,
37	                        post.status === "published" ? css.statusPublished : css.statusDraft,
38	                      )}
39	                    >
40	                      {post.status}
41	                    </span>
42	                    <span>Updated {new Date(post.updatedAt).toLocaleDateString()}</span>
43	                  </div>
44	                </Card>
45	              </Link>
46	            </li>
47	          ))}
48	        </ul>
49	      )}
50	    </section>
51	  );
52	}

