  1	import { useMutation, useQuery } from "@tanstack/react-query";
  2	import { useEffect, useState } from "react";
  3	import { useParams } from "react-router";
  4	import { Button } from "../components/Button/Button";
  5	import { PublishToast } from "../components/PublishToast/PublishToast";
  6	import { trackEvent } from "../lib/analytics";
  7	import { getPostPublishMutationOptions } from "../queries/posts/post-publish-mutation";
  8	import { getPostQueryOptions } from "../queries/posts/post-query";
  9	import { getPostSaveMutationOptions } from "../queries/posts/post-save-mutation";
 10	import { rootLogger } from "../../shared/logger";
 11	import type { Post } from "../types";
 12	import css from "./PostEditorPage.module.css";
 13	
 14	const logger = rootLogger.child("post-editor");
 15	
 16	interface ToastState {
 17	  readonly tone: "success" | "error";
 18	  readonly message: string;
 19	}
 20	
 21	export function PostEditorPage() {
 22	  const { siteSlug = "", postId: postIdParam = "" } = useParams();
 23	  const postId = Number(postIdParam);
 24	  const postQuery = useQuery(getPostQueryOptions(siteSlug, postId));
 25	
 26	  if (postQuery.isPending) return <p>Loading post…</p>;
 27	  if (postQuery.isError) return <p role="alert">Couldn't load this post.</p>;
 28	
 29	  // Keyed by the post's own id, so navigating straight from one post to
 30	  // another remounts the form with that post's own content instead of
 31	  // syncing local state to it through an effect.
 32	  return (
 33	    <PostEditorForm
 34	      key={postQuery.data.id}
 35	      siteSlug={siteSlug}
 36	      postId={postId}
 37	      post={postQuery.data}
 38	    />
 39	  );
 40	}
 41	
 42	function PostEditorForm({
 43	  siteSlug,
 44	  postId,
 45	  post,
 46	}: Readonly<{ siteSlug: string; postId: number; post: Post }>) {
 47	  const saveMutation = useMutation(getPostSaveMutationOptions(siteSlug, postId));
 48	  const publishMutation = useMutation(getPostPublishMutationOptions(siteSlug, postId));
 49	
 50	  const [title, setTitle] = useState(post.title);
 51	  const [body, setBody] = useState(post.body);
 52	  const [toast, setToast] = useState<ToastState | null>(null);
 53	
 54	  useEffect(() => {
 55	    if (!toast) return;
 56	    const timer = window.setTimeout(() => setToast(null), 3000);
 57	    return () => window.clearTimeout(timer);
 58	  }, [toast]);
 59	
 60	  function handleSaveDraft() {
 61	    saveMutation.mutate(
 62	      { title, body },
 63	      { onSuccess: () => trackEvent("draft saved", { site_slug: siteSlug, post_id: postId }) },
 64	    );
 65	  }
 66	
 67	  function handlePublish() {
 68	    publishMutation.mutate(undefined, {
 69	      onSuccess: (result) => {
 70	        trackEvent("post published", { site_slug: siteSlug, post_id: postId });
 71	        setToast(
 72	          result.deployTriggered
 73	            ? { tone: "success", message: "Published. The site will rebuild shortly." }
 74	            : {
 75	                tone: "error",
 76	                message:
 77	                  "Published, but the deploy didn't fire — you may need to trigger it yourself.",
 78	              },
 79	        );
 80	      },
 81	      onError: () => {
 82	        logger.warn(
 83	          { siteSlug, postId },
 84	          "A publish request failed; the editor will let the author retry.",
 85	        );
 86	        setToast({ tone: "error", message: "Publishing failed. Try again." });
 87	      },
 88	    });
 89	  }
 90	
 91	  return (
 92	    <section className={css.editor}>
 93	      <p className={css.status}>Status: {post.status}</p>
 94	
 95	      <label className={css.field}>
 96	        <span className={css.label}>Title</span>
 97	        <input
 98	          className={css.titleInput}
 99	          value={title}
100	          onChange={(event) => setTitle(event.target.value)}
101	        />
102	      </label>
103	
104	      <label className={css.field}>
105	        <span className={css.label}>Body</span>
106	        <textarea
107	          className={css.bodyInput}
108	          rows={16}
109	          value={body}
110	          onChange={(event) => setBody(event.target.value)}
111	        />
112	      </label>
113	
114	      <div className={css.actions}>
115	        <Button
116	          variant="secondary"
117	          loading={saveMutation.isPending}
118	          error={saveMutation.isError}
119	          onClick={handleSaveDraft}
120	        >
121	          {saveMutation.isPending ? "Saving…" : "Save draft"}
122	        </Button>
123	        <Button
124	          loading={publishMutation.isPending}
125	          error={publishMutation.isError}
126	          onClick={handlePublish}
127	        >
128	          {publishMutation.isPending ? "Publishing…" : "Publish"}
129	        </Button>
130	      </div>
131	
132	      {toast && <PublishToast tone={toast.tone} message={toast.message} />}
133	    </section>
134	  );
135	}

